/* eslint-disable no-undef */
import { Component, Element, h, Host, Prop } from '@stencil/core';

/**
 *
 */
@Component({
  tag: 'groupui-stepper-horizontal',
  styleUrl: 'stepper-horizontal.scss',
  shadow: true,
})
export class StepperHorizontal {
  @Element() host: HTMLElement;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly condensed: boolean;

  componentDidLoad() {
    this.setStepNumbers();
  }

  private rerenderOnSlotChange = () => {
    this.setStepNumbers();
  };

  private setStepNumbers() {
    let number = 1;
    const steps = this.host.querySelectorAll('groupui-step');
    steps.forEach((groupuiStep: HTMLGroupuiStepElement) => {
      groupuiStep.number = number;
      groupuiStep.classList.add('step-horizontal');
      number++;
    });
  }

  render() {
    return (
      <Host>
        <div id="stepper-steps" role="list" aria-label="progress">
          <slot onSlotchange={this.rerenderOnSlotChange}> </slot>
        </div>
      </Host>
    );
  }
}
